std::timed_mutex mtx;

// Fast path check (zero overhead if uncontended)
if (mtx.try_lock()) {
    // Acquire successful
    mtx.unlock();
}

// Short, relative wait (often implemented via internal spinning/yield loops)
bool short_wait = mtx.try_lock_for(std::chrono::milliseconds(1));

// Long, absolute wait (Requires OS primitive: futex, WaitForSingleObject, etc.)
// OS timer resolution impacts accuracy, especially for small durations.
auto limit = std::chrono::steady_clock::now() + std::chrono::seconds(5);
if (mtx.try_lock_until(limit)) {
    // Critical Section
    mtx.unlock();
}

// Note: High frequency calls to try_lock_for/until increase kernel transitions.
